//! FlatBuffers tables generated by `flatc` from `rust/ffi/schema`.
//!
//! Regenerate with `dart run tool/generate_bindings.dart`; do not edit.
//!
//! The generated code is not ours to keep tidy, and it predates several
//! current idioms, so the lints it trips are switched off here rather than
//! in the crate root — this keeps them on for the hand-written shim, where
//! they are worth having.
//!
//! Notably `unsafe_op_in_unsafe_fn`: flatc emits bodies that rely on the
//! pre-2024 rule that the body of an `unsafe fn` is implicitly unsafe.
#![allow(
    clippy::all,
    dead_code,
    mismatched_lifetime_syntaxes,
    missing_debug_implementations,
    unsafe_op_in_unsafe_fn,
    unused_imports
)]

pub mod abi_generated;
pub mod chunk_generated;
pub mod document_generated;
pub mod find_generated;
pub mod highlight_generated;
